// src/lib/ai/batch.ts
function batchByChars(items, sizeOf, limit, max = Infinity) {
  const batches = [];
  let size = 0;
  for (const item of items) {
    const n = sizeOf(item);
    if (!batches.length || size + n > limit || batches[batches.length - 1].length >= max) {
      batches.push([]);
      size = 0;
    }
    batches[batches.length - 1].push(item);
    size += n;
  }
  return batches;
}

